import * as M from './core.js?v=2.4';
import {durationMinutes,progressMetrics} from './progress.js';
import { motivationForDay, saveReminder, normalizeExtras, LEGISLATION_QUEUE} from './personal.js';
const $=q=>document.querySelector(q), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), label=id=>M.RULES[id]?.label||id.replace('legacy:',''), option=(v,t,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(t)}</option>`, checks=v=>v?'checked':'', cpLabel={done:'Concluído',due:'Checkpoint pendente',battery:'Baterias pendentes',audit:'Conferir histórico',planned:'Planejado'}, phaseLabel={new:'Estudo Novo',solid:'Estudo Sólido'};
let state,page='today',selected='afo',pendingImport=null,timer=null,lawTimer=null,storedRaw=null,noticeTimeout;
const main=$('#main'), modal=$('#modal');
function toast(message,error=false){if(modal.open&&error){let box=$('#modal-error');if(!box){box=document.createElement('p');box.id='modal-error';box.className='warning';box.setAttribute('role','alert');$('#modal-body').prepend(box);}box.textContent=message;box.scrollIntoView({block:'nearest'});}clearTimeout(noticeTimeout);$('#notice').textContent=message;$('#notice').className=error?'error':'';noticeTimeout=setTimeout(()=>$('#notice').textContent='',error?12000:5500);}
function persist(next){next.updatedAt=new Date().toISOString();let raw=JSON.stringify(next);try{if(localStorage.getItem(M.KEY)!==storedRaw)throw Error('Os dados mudaram em outra aba. Recarregue antes de salvar.');localStorage.setItem(M.KEY,raw);}catch(e){throw Error('Não foi possível salvar. '+e.message);}storedRaw=raw;state=next;}
function change(fn,message='Registro salvo neste dispositivo.'){try{persist(fn());render();toast(message);return true;}catch(e){toast(e.message,true);return false;}}
function open(html){$('#modal-body').innerHTML=html;modal.showModal();}
function close(){modal.close();$('#modal-body').innerHTML='';}
$('#close-modal').onclick=close;
function download(name,body,type='application/json'){let url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function backup(){download('Metodo-ET-'+M.day()+'.json',JSON.stringify(state,null,2));}
function subject(id=selected){return state.subjects.find(s=>s.id===id);}
function heading(kicker,title,description,action=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function tabs(){return `<div class="tabs">${['afo','dad','ti','port','dcon'].map(id=>`<button class="secondary" data-select="${id}" aria-pressed="${selected===id}">${label(id)}</button>`).join('')}</div>`;}
function actionsButton(text,act,extra=''){return `<button data-action="${act}" ${extra}>${text}</button>`;}
function archivedStudyOSStates(){return (state.archive||[]).map(a=>a?.payload?.state||a?.payload).filter(src=>Array.isArray(src?.topics));}
function afoVideoLessons(s,u){if(s?.id!=='afo'||!u)return[];let prefix=String(u.title||'').trim()+' — ',found=new Map();for(let src of archivedStudyOSStates())for(let t of src.topics||[]){if(t?.disciplineId!=='afo')continue;let full=String(t.title||'').trim();if(!full.startsWith(prefix))continue;let text=String(t.details||full.slice(prefix.length)).trim();if(!text||/^PDF\s*—/i.test(text))continue;let order=Number(t.order)||999999;if(!found.has(text)||order<found.get(text))found.set(text,order);}for(let e of u.legacy||[]){let full=String(e.title||'').trim();if(!full.startsWith(prefix))continue;let text=full.slice(prefix.length).trim();if(text&&!/^PDF\s*—/i.test(text)&&!found.has(text))found.set(text,999999+found.size);}return [...found.entries()].sort((a,b)=>a[1]-b[1]||a[0].localeCompare(b[0],'pt-BR')).map(([title])=>title);}
function sessionContentField(s,u,selected=''){let items=afoVideoLessons(s,u);if(s?.id==='afo'&&u&&items.length)return `<label class="full">Conteúdo estudado / videoaula<select name="title" id="session-content">${option('','Selecionar videoaula',selected)}${items.map(t=>option(t,t,selected)).join('')}</select></label><label class="full">Outro conteúdo (se não estiver na lista)<input name="customTitle" value="${esc(selected&&!items.includes(selected)?selected:'')}" placeholder="Digite somente se não estiver na lista"></label>`;return `<label class="full">Conteúdo estudado (opcional)<input name="title" value="${esc(selected)}" placeholder="Ex.: leitura complementar ou resolução de questões"></label>`;}
function refreshSessionContent(){let form=$('#session-form');if(!form)return;let s=subject(form.elements.subjectId.value),u=s?.units.find(u=>u.id===form.elements.unitId.value),wrap=$('#session-content-wrap');if(wrap)wrap.innerHTML=sessionContentField(s,u,'');}
function suggestedTheoryDate(u){let dates=(u?.legacy||[]).map(e=>e.date).filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d||'')).sort();return dates.at(-1)||'';}
function currentSubject(){return subject(M.CYCLE[state.cycle.index]);}
function lawState(){return state.legislation;}
function currentLaw(){let l=lawState();return l.queue[Math.min(l.current,l.queue.length-1)]||l.queue[0];}
function lawElapsed(){return lawTimer?lawTimer.elapsed+(lawTimer.running?Date.now()-lawTimer.started:0):0;}
function saveLawTimer(){try{if(lawTimer)localStorage.setItem(M.KEY+':law-timer',JSON.stringify(lawTimer));else localStorage.removeItem(M.KEY+':law-timer');}catch{toast('O cronômetro da legislação está apenas em memória. Registre o tempo antes de fechar a app.',true);}}
function updateLawClock(){let el=$('#law-clock');if(!el)return;let sec=Math.floor(lawElapsed()/1000);el.textContent=[Math.floor(sec/3600),Math.floor(sec/60)%60,sec%60].map(n=>String(n).padStart(2,'0')).join(':');let target=$('#law-target');if(target)target.textContent=sec>=600?'Meta diária de 10 min alcançada.':Math.max(0,600-sec)+' s para 10 min';}
function lawLastRef(normId){let rows=lawState().sessions.filter(x=>x.normId===normId).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));return rows[0]?.endRef||rows[0]?.startRef||'';}
function legislationPage(){let l=lawState(),norm=currentLaw(),today=l.sessions.filter(x=>x.date===M.day()).reduce((a,x)=>a+x.minutes,0),total=l.sessions.reduce((a,x)=>a+x.minutes,0),rows=[...l.sessions].sort((a,b)=>b.date.localeCompare(a.date)||String(b.createdAt).localeCompare(String(a.createdAt))),completed=new Set(l.completed.map(x=>x.normId));return heading('10 MINUTOS TODOS OS DIAS','Legislação Seca','Uma norma por vez, do início ao fim. Esta rotina é complementar e não altera o ciclo principal.')+`<div class="grid two"><section class="card hero"><span class="eyebrow">NORMA ATUAL</span><h2>${esc(norm.short)}</h2><p>${esc(norm.title)}</p><div class="timer" id="law-clock">00:00:00</div><div class="actions">${lawTimer?actionsButton(lawTimer.running?'Pausar':'Continuar','law-timer-toggle')+actionsButton('Registrar tempo','law-timer-save','class="secondary"'):actionsButton('Iniciar 10 minutos','law-timer-start')+actionsButton('Registrar manualmente','law-manual','class="secondary"')}</div><div class="statline"><span>Hoje: <b>${today} min</b></span><span>Total: <b>${M.hm(total)}</b></span><span id="law-target">${today>=10?'Meta diária alcançada.':10-today+' min para a meta'}</span></div><p class="muted" style="font-size:13px">${lawLastRef(norm.id)?'Retomar de: '+esc(lawLastRef(norm.id)):'Comece do início da norma e registre onde parou.'}</p><button class="secondary" data-action="law-complete">Concluir esta norma e avançar</button></section><section class="card"><h2>Regra da rotina</h2><p class="muted">Leia a mesma norma diariamente até terminá-la. Somente depois avance para a próxima da fila.</p><p class="muted">O cronômetro usa 10 minutos como referência, mas o registro manual aceita o tempo real estudado.</p><div class="warning">A LINDB não integra esta fila: ela não aparece expressamente nos conteúdos programáticos dos editais TCU 2021/2022 e TCU 2025/2026 usados como referência.</div></section></div><section class="card section-title"><h2>Fila de leitura</h2><div class="table-wrap"><table><thead><tr><th>ORDEM</th><th>NORMA</th><th>SITUAÇÃO</th></tr></thead><tbody>${l.queue.map((x,i)=>`<tr><td>${i+1}</td><td><b>${esc(x.short)}</b><small style="display:block">${esc(x.title)}</small></td><td>${completed.has(x.id)?'<span class="badge">Concluída</span>':i===l.current?'<span class="badge">Em leitura</span>':'Planejada'}</td></tr>`).join('')}</tbody></table></div></section><section class="card section-title"><h2>Histórico da Legislação Seca</h2>${rows.length?`<div class="table-wrap"><table><thead><tr><th>DATA</th><th>NORMA</th><th>TEMPO</th><th>LEITURA</th><th>ANOTAÇÃO</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(l.queue.find(n=>n.id===x.normId)?.short||x.normId)}</td><td>${x.minutes} min</td><td>${esc([x.startRef,x.endRef].filter(Boolean).join(' → ')||'—')}</td><td>${esc(x.notes||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma leitura registrada ainda.</div>'}</section>`;}
function lawManualDialog(defaultMinutes=10,source='manual'){let norm=currentLaw();open(`<h2>Registrar Legislação Seca</h2><p class="muted"><b>${esc(norm.short)}</b> · ${esc(norm.title)}</p><form id="law-form" class="form-grid"><label>Data<input required type="date" name="date" value="${M.day()}" max="${M.day()}"></label><label>Minutos<input required type="number" min="1" max="1440" step="1" name="minutes" value="${defaultMinutes}"></label><label>Ponto inicial<input name="startRef" maxlength="120" placeholder="Ex.: art. 1º"></label><label>Ponto final<input name="endRef" maxlength="120" placeholder="Ex.: art. 12"></label><label class="full">Anotação opcional<textarea name="notes" maxlength="2000" placeholder="Ex.: retomar no art. 13"></textarea></label><button class="full">Salvar leitura</button></form>`);$('#law-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),minutes=Number(d.minutes);if(!M.validDay(d.date)||d.date>M.day()||!Number.isInteger(minutes)||minutes<1||minutes>1440){toast('Confira a data e o tempo da leitura.',true);return;}if(change(()=>{let next=M.copy(state),l=next.legislation,n=l.queue[l.current];l.sessions.push({id:M.uid(),normId:n.id,date:d.date,minutes,startRef:String(d.startRef||'').trim(),endRef:String(d.endRef||'').trim(),notes:String(d.notes||'').trim(),source,createdAt:new Date().toISOString()});return next;},'Leitura de legislação registrada.')){close();}};}
function completeLawDialog(){let norm=currentLaw();open(`<h2>Concluir ${esc(norm.short)}</h2><p class="muted">Confirme somente depois de chegar ao final da norma. A próxima da fila será liberada automaticamente.</p><form id="law-complete-form"><button>Concluir norma e avançar</button></form>`);$('#law-complete-form').onsubmit=e=>{e.preventDefault();if(change(()=>{let next=M.copy(state),l=next.legislation,n=l.queue[l.current];if(!l.completed.some(x=>x.normId===n.id))l.completed.push({normId:n.id,date:M.day(),at:new Date().toISOString()});if(l.current<l.queue.length-1)l.current++;return next;},'Norma concluída. Próxima leitura liberada.'))close();};}
function render(){page=location.hash.slice(1)||'today';if(!['today','progress','subjects','solid','planning','history','legislation','data','reminders','motivation'].includes(page))page='today';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));main.innerHTML=({today:todayPage,progress:progressPage,subjects:subjectsPage,solid:solidPage,planning:planningPage,history:historyPage,legislation:legislationPage,data:dataPage,reminders:remindersPage,motivation:motivationPage}[page])();updateClock();updateLawClock();}
function todayPage(){const t=M.totals(state),s=currentSubject(),nt=M.nightTasks(state),audit=state.subjects.flatMap(s=>M.checkpoints(s).filter(c=>c.status==='audit').map(c=>`${label(s.id)} · bloco ${c.number}`)),slots=state.sessions.filter(x=>x.date===M.day()&&x.slotComplete).length;return '<aside class="focus-message"><p><strong>Estude para ser o primeiro lugar, não apenas para passar!</strong></p><small>Lembre-se: sua mente calibra o esforço de acordo com seu pensamento.</small></aside>'+heading('SEU COMPROMISSO COM O PRIMEIRO LUGAR','Vamos avançar, Douglas.','Teoria com direção. Questões com intenção. Revisão todos os dias.',actionsButton('+ Registrar estudo','session'))+`<div class="grid metrics"><div class="card metric"><small>CARGA SEMANAL</small><strong>${M.hm(t.week)} <span class="muted" style="font-size:16px">/ 30h mín.</span></strong><progress max="1800" value="${Math.min(t.week,1800)}" aria-label="Carga semanal"></progress><span class="sub">${t.week>=1800?'Meta mínima alcançada. Siga seu planejamento.':M.hm(1800-t.week)+' para a meta mínima'} · sem revisão noturna</span></div><div class="card metric"><small>ESTUDO DE HOJE</small><strong>${M.hm(t.day)}</strong><span class="sub">${slots} de 3 blocos do ciclo concluídos</span><progress max="3" value="${Math.min(slots,3)}" aria-label="Blocos do dia"></progress><span class="sub">Meta diária: concluir os três blocos previstos</span></div><div class="card metric"><small>FECHAMENTO DO DIA</small><strong>${nt.filter(x=>x.done).length}<span class="muted" style="font-size:16px"> / ${nt.length} revisões</span></strong><span class="sub">${t.night} min de revisão noturna</span><progress max="${nt.length||1}" value="${nt.filter(x=>x.done).length}" aria-label="Revisões noturnas"></progress><span class="sub">Registrada à parte das metas de estudo</span></div></div><div class="grid two"><div class="stack"><section class="card hero"><span class="eyebrow">${timer?'SESSÃO EM ANDAMENTO':'AGORA NO SEU CICLO'}</span><h2>${label(timer?.subjectId||s.id)} <span class="phase">${phaseLabel[s.phase]}</span></h2><p class="muted">${esc(timer?timer.title:M.nextAction(s))}</p><div class="timer" id="clock">00:00:00</div><div class="actions">${timer?actionsButton(timer.running?'Pausar':'Continuar','timer-toggle')+actionsButton('Registrar tempo','timer-save','class="secondary"'):actionsButton('Iniciar foco','timer-start')+actionsButton('Ver disciplina','go-subject','class="secondary"')}</div><div class="statline"><span>Bloco de <b>${M.hm(s.slotMinutes)}</b></span><span><b>${state.cycle.minutes} min</b> já realizados</span><span>Restam <b>${M.hm(s.slotMinutes-state.cycle.minutes)}</b></span></div></section><section class="card"><h2>Seu ciclo, sem recomeçar</h2><p class="muted" style="font-size:13px">Três disciplinas por dia. Retome de onde parou.</p><div class="cycle">${M.CYCLE.map((id,i)=>`<span class="${i===state.cycle.index?'current':''}">${i+1}. ${label(id)}</span>`).join('')}</div><small>${new Date().getDay()===0?'Domingo: descanso ou recuperação do que ficou pendente.':'Próximos três blocos: '+[0,1,2].map(n=>label(M.CYCLE[(state.cycle.index+n)%6])).join(' → ')}</small></section></div><div class="stack"><section class="card"><span class="eyebrow">ÚLTIMA ETAPA, SEMPRE</span><h2 style="margin-top:10px">Revisão noturna</h2><p class="muted" style="font-size:13px">5 a 10 minutos por disciplina estudada. Encerre o dia recuperando os pontos principais.</p>${nt.length?nt.map(n=>`<div class="row"><div class="title">${label(n.id)}<small>${n.done?'Revisão registrada':'Pendente para fechar o dia'}</small></div>${n.done?'<span class="badge">✓ Feita</span>':`<button class="secondary small" data-action="night" data-id="${n.id}">Revisar</button>`}</div>`).join(''):'<div class="empty">As disciplinas aparecem aqui após o primeiro estudo do dia.</div>'}</section><section class="card"><h2>Pontos de atenção</h2>${audit.length?`<div class="warning">Avanço anterior encontrado em ${audit.join(' e ')}. Confira a conclusão das aulas e baterias para validar esses checkpoints.</div>`:'<p class="muted">Confira os próximos passos nas disciplinas.</p>'}<p class="muted" style="font-size:13px">AFO: checkpoints a cada <b style="color:var(--text)">3 módulos</b>. Nas demais disciplinas ativas, a cada 4 aulas.</p><a href="#subjects">Conferir disciplinas →</a></section></div></div>`;}
function subjectsPage(){let s=subject(),cps=M.checkpoints(s);return heading('CONTROLE PRÉ-EDITAL','Disciplinas','A mesma sequência das planilhas, com o seu histórico preservado.')+tabs()+`<section class="card"><div class="page-head"><div><h2>${esc(s.course)}</h2><p>${s.units.length} ${M.RULES[s.id].unit==='módulo'?'módulos':'aulas'} · ${phaseLabel[s.phase]} · ${M.hm(s.slotMinutes)} por bloco</p></div><span class="badge">Checkpoint a cada ${M.RULES[s.id].checkpoint}</span></div><div class="statline"><span>Teoria <b>${s.units.filter(u=>u.theoryDone).length}/${s.units.length}</b></span><span>Baterias <b>${s.units.filter(u=>u.batteryDone).length}/${s.units.length}</b></span><span>Checkpoints <b>${cps.filter(c=>c.status==='done').length}/${cps.length}</b></span><span>Revisão geral <b>${s.units.filter(u=>u.generalDone).length}/${s.units.length}</b></span></div><p class="muted" style="font-size:13px">${esc(M.nextAction(s))}</p>${s.id==='port'?`<label class="check"><input type="checkbox" id="andresan" ${checks(s.andresanComplete)}> Confirmei a conclusão dos cursos do professor Andresan</label><small>O curso teórico atual, sozinho, não conclui Português.</small>`:''}<div class="table-wrap"><table><thead><tr><th>${s.id==='afo'?'MÓDULO':'AULA'}</th><th>NOME</th><th>SITUAÇÃO</th><th>1ª RESOLUÇÃO</th><th>CHECKPOINT</th><th>REVISÃO GERAL</th><th>CONTROLE</th></tr></thead><tbody>${cps.map(cp=>cp.units.map(u=>`<tr><td class="numbers">${String(u.order).padStart(2,'0')}</td><td class="unit-title">${esc(u.title)}</td><td>${M.unitSituation(u)}</td><td>${M.pct(u.battery)}<small style="display:block">${u.battery.attempted} questões</small></td><td>${M.pct(cp.record?.perUnit?.[u.id])}</td><td>${M.pct(u.general)}</td><td><button class="secondary small" data-action="unit" data-id="${u.id}">Abrir</button></td></tr>`).join('')+`<tr class="cp-row ${cp.status==='audit'?'audit':''}"><td colspan="2"><b>◇ CHECKPOINT ${cp.number}</b> · ${cp.units.length} ${s.id==='afo'?'módulos':'aulas'}${cp.partial?' · último bloco':''}</td><td colspan="4">${cpLabel[cp.status]}${cp.status==='audit'?' · histórico não equivale à conclusão no ET':''}</td><td><button class="secondary small" data-action="checkpoint" data-id="${cp.id}">${cp.status==='done'?'Ver':'Abrir'}</button></td></tr>`).join('')}</tbody></table></div><div class="actions">${s.phase==='new'?`<button data-action="to-solid" ${M.canSolid(s)?'':'disabled'}>Passar ao Estudo Sólido</button><small>Exige revisão geral, material e todos os checkpoints.</small>`:'<a href="#solid">Abrir cadernos do Estudo Sólido →</a>'}</div></section>`;}
function solidPage(){let s=subject();const names={main:'Resolver caderno completo',errors:'Refazer erros até zerar',favorites:'Refazer favoritas',done:'Caderno concluído'};return heading('CONSOLIDAÇÃO','Estudo Sólido','Menos carga horária. Mais precisão nas questões.')+tabs()+`<section class="card"><h2>${label(s.id)} · ${phaseLabel[s.phase]}</h2>${s.phase!=='solid'?`<p class="muted">Finalize teoria, baterias, checkpoints, revisão geral e material de revisão para entrar nesta fase.</p><p class="muted">${esc(M.nextAction(s))}</p><a href="#subjects">Abrir controle pré-edital →</a>`:`<p class="muted">Carga reduzida para ${M.hm(s.slotMinutes)} por bloco. Volte à teoria quando necessário.</p><button data-action="notebook-new">+ Caderno TEC</button>${s.notebooks.map(n=>`<div class="row"><div><h3>${esc(n.title)}</h3><small>${names[n.stage]} · ${n.target} questões${n.stage==='errors'?' · '+n.errors+' erros a refazer':''}</small>${n.url?`<a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">Abrir TEC ↗</a>`:''}<details><summary>Rodadas registradas</summary>${n.log.map(l=>`<p>${l.date} · ${names[l.stage]} · ${l.correct}/${l.attempted}</p>`).join('')}</details></div>${n.stage==='done'?'<span class="badge">Concluído</span>':`<button class="secondary" data-action="notebook-round" data-id="${n.id}">Concluir rodada</button>`}</div>`).join('')}`}</section><section class="card section-title"><h2>Sequência de cada caderno</h2><p class="muted">Caderno aleatório → questões erradas até zerar → favoritas → erros das favoritas até zerar → novo caderno.</p><small>Registre o tempo de cada sessão no diário. Os resultados das rodadas controlam a passagem entre etapas.</small></section>`;}
function planningPage(){let per=Object.fromEntries(state.subjects.map(s=>[s.id,M.CYCLE.filter(id=>id===s.id).length*s.slotMinutes*3])),total=Object.values(per).reduce((a,b)=>a+b,0);return heading('DIREÇÃO E CONSISTÊNCIA','Planejamento','TCU como concurso principal. CGU como possibilidade secundária.')+`<div class="grid two"><section class="card"><h2>30 horas são o mínimo.</h2><p class="muted">Seu ciclo inicial completo, repetido de segunda a sábado, prevê 34h30 de estudo. As revisões noturnas ficam fora dessa carga.</p><div class="cycle">${M.CYCLE.map((id,i)=>`<span>${i+1}. ${label(id)}</span>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>DIAS DO CICLO</th><th>DISCIPLINAS</th><th>CARGA</th></tr></thead><tbody>${[0,1].map(n=>`<tr><td>${n?'Ter · Qui · Sáb':'Seg · Qua · Sex'}</td><td>${M.CYCLE.slice(n*3,n*3+3).map(label).join(' → ')}</td><td>${M.hm(M.CYCLE.slice(n*3,n*3+3).reduce((a,id)=>a+subject(id).slotMinutes,0))}</td></tr>`).join('')}<tr><td>Domingo</td><td>Descanso ou recuperação</td><td>Flexível</td></tr></tbody></table></div><p class="muted" style="font-size:13px;margin-top:16px">Esta é a distribuição de referência a partir de AFO. Se houver uma interrupção, o ciclo continua da posição salva.</p><h3 class="section-title">Fechamento diário</h3><p class="muted">3 disciplinas + revisão noturna de 5–10 minutos por disciplina. A revisão aparece no total do dia à parte e não compõe as metas.</p></section><section class="card"><h2>Carga por disciplina</h2>${['afo','dad','ti','port','dcon'].map(id=>`<div class="chartbar"><span>${label(id)}</span><div><i style="width:${per[id]/Math.max(...Object.values(per))*100}%"></i></div><b>${M.hm(per[id])}</b></div>`).join('')}<div class="row"><span>Total previsto atual</span><b>${M.hm(total)}</b></div>${total<1800?'<div class="warning">A redução de carga no Estudo Sólido deixou a projeção abaixo de 30h. Complete a semana com sessões adicionais registradas no diário.</div>':''}<small>Tempo de Estudo Sólido usa a carga reduzida que você definiu.</small></section></div><section class="card section-title"><h2>Regras do seu método</h2><div class="grid form-grid"><div><h3>Estudo Novo</h3><p class="muted">Teoria sequencial; bateria de 30–50 questões, em outro dia, cobrindo a aula; checkpoints; revisão geral com produção ou adaptação do material de revisão.</p><small>Microrrevisão inicial: até 10% do bloco, dentro da carga de estudo.</small></div><div><h3>Exceções Pacelli</h3><p class="muted">AFO e CPU: checkpoint a cada 3 módulos completos. DAD, TI, DCON e Português: a cada 4 tópicos/aulas. O último bloco também recebe checkpoint.</p><small>CPU está prevista nas regras, sem integrar as cinco disciplinas atuais. Estudo Final fica reservado ao pós-edital.</small></div></div></section>`;}
function historyPage(){return heading('TEMPO, CONTEÚDO E RENDIMENTO','Diário de estudo','Histórico do StudyOS e registros do novo método, no mesmo lugar.',actionsButton('+ Registrar','session'))+`<section class="card"><div class="inline-filter"><label>Disciplina<select id="history-subject">${option('','Todas','')}${[...new Set(state.sessions.map(s=>s.subjectId))].sort().map(id=>option(id,label(id),'')).join('')}</select></label><label>A partir de<input id="history-from" type="date"></label><label>Até<input id="history-to" type="date"></label><button class="secondary" data-action="csv">Exportar CSV</button></div><div id="history-results">${historyRows()}</div></section>`;}
function filteredHistory(){let sid=$('#history-subject')?.value||'',from=$('#history-from')?.value||'',to=$('#history-to')?.value||'';return state.sessions.filter(x=>(!sid||x.subjectId===sid)&&(!from||x.date>=from)&&(!to||x.date<=to)).sort((a,b)=>b.date.localeCompare(a.date)||String(b.createdAt).localeCompare(String(a.createdAt)));}
function historyRows(){let rows=filteredHistory(),mins=rows.filter(s=>s.activity!=='night').reduce((a,s)=>a+s.minutes,0),night=rows.filter(s=>s.activity==='night').reduce((a,s)=>a+s.minutes,0),q=rows.reduce((a,s)=>a+s.questions,0),c=rows.reduce((a,s)=>a+s.correct,0);let speed=['pdf','video'].map(m=>{let r=rows.filter(s=>s.medium===m&&s.start!==null&&s.end!==null),time=r.reduce((a,s)=>a+s.minutes,0),distance=r.reduce((a,s)=>a+s.end-s.start,0);return time?`${m==='pdf'?'Páginas/h':'Min de vídeo/h'}: ${(distance*60/time).toFixed(1)}`:'';}).filter(Boolean);return `<div class="statline"><span><b>${rows.length}</b> registros</span><span>Estudo: <b>${M.hm(mins)}</b></span><span>Noturna: <b>${M.hm(night)}</b></span><span>Questões: <b>${q}</b> · ${M.pct({attempted:q,correct:c})}</span>${speed.map(s=>`<span>${s}</span>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>DATA</th><th>MATÉRIA / AULA</th><th>FORMA</th><th>INÍCIO → FIM</th><th>TEMPO</th><th>QUESTÕES</th><th>ANOTAÇÕES</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(s.date)}${s.legacy?'<small style="display:block">StudyOS</small>':''}</td><td class="unit-title"><b>${esc(label(s.subjectId))}</b><small style="display:block">${esc(s.title||'Sem vínculo a uma aula atual')}</small></td><td>${M.ACTIVITIES[s.activity]}${s.medium?'<small style="display:block">'+esc(s.medium)+'</small>':''}</td><td>${s.start===null?'—':s.start+' → '+s.end}</td><td>${M.hm(s.minutes)}${s.activity==='night'?'<small style="display:block">fora da meta</small>':''}</td><td>${s.questions?s.correct+'/'+s.questions:'—'}</td><td>${s.notes?`<details><summary>Ler</summary>${esc(s.notes)}</details>`:'—'}</td></tr>`).join('')}</tbody></table></div>`;}
function dataPage(){return heading('CONTINUIDADE DOS SEUS ESTUDOS','Dados e segurança','Seu novo projeto preserva o histórico anterior.')+`<div class="grid two"><section class="card"><h2>Seu progresso, com você</h2><p class="muted">Os registros desta versão ficam neste navegador. Exporte um backup após estudar para poder recuperar os dados ou levá-los a outro dispositivo.</p><div class="actions"><button data-action="export">Exportar backup completo</button><button class="secondary" data-action="import">Importar backup</button></div><div class="statline"><span><b>${state.sessions.length}</b> sessões</span><span><b>${state.imports.length}</b> importações StudyOS</span><span>Última gravação: <b>${state.updatedAt?new Date(state.updatedAt).toLocaleString('pt-BR'):'base inicial'}</b></span></div><p class="muted" style="font-size:13px">Importar StudyOS mescla registros sem duplicar IDs e preserva o arquivo original no backup exportado. Restaurar Metodo-ET substitui os dados locais após conferir o resumo.</p><div class="warning">A sincronização com o Google Drive é controlada pelo botão de nuvem. Seus dados também permanecem salvos localmente neste dispositivo.</div></section><section class="card"><h2>Fontes do projeto</h2><div class="link-list"><a href="https://docs.google.com/spreadsheets/d/1uMl-NmHvoyk9akx0Yr472woQh8RPD3hDWn82FX1Ix8M/edit" target="_blank" rel="noopener">Controle Estudo Total ↗</a><a href="https://docs.google.com/spreadsheets/d/16FH4If1ZjL1q5VWER90LluQhNfNGWINZdc2KgwEmJTI/edit" target="_blank" rel="noopener">Planilha pré-edital ↗</a><a href="https://github.com/douglasborges/Metodo-ET" target="_blank" rel="noopener">Repositório Metodo-ET ↗</a></div><p class="muted" style="font-size:13px;margin-top:20px">As planilhas orientam os fluxos. O histórico antigo é evidência para conferência: estudar uma aula não comprova ter concluído sua bateria ou seu checkpoint.</p></section></div>`;}
function sessionDialog(defaults={}){let sid=defaults.subjectId||currentSubject().id,s=subject(sid);open(`<h2>Registrar estudo</h2><p class="muted">Registre a sessão exatamente onde você estudou. Registrar tempo não conclui automaticamente o módulo nem valida etapas anteriores.</p><form id="session-form" class="form-grid"><label>Disciplina<select name="subjectId" id="session-subject">${state.subjects.map(s=>option(s.id,label(s.id),sid)).join('')}</select></label><label>Atividade<select name="activity" id="session-activity">${Object.entries(M.ACTIVITIES).map(([id,t])=>option(id,t,defaults.activity||'free')).join('')}</select></label><label class="full">Aula ou módulo<select name="unitId" id="session-unit">${unitOptions(s,defaults.unitId)}</select></label><div id="session-content-wrap" class="full">${sessionContentField(s,s.units.find(u=>u.id===defaults.unitId),defaults.title||'')}</div><label>Data<input required type="date" name="date" value="${M.day()}" max="${M.day()}"></label><div class="duration-fields"><label>Horas<input required type="number" min="0" max="24" step="1" name="hours" value="${Math.floor((defaults.minutes||0)/60)}"></label><label>Minutos<input required type="number" min="0" max="59" step="1" name="durationMinutes" value="${(defaults.minutes||0)%60}"></label></div><label>Questões resolvidas<input type="number" min="0" step="1" name="questions" value="0"></label><label>Acertos<input type="number" min="0" step="1" name="correct" value="0"></label><label>Formato<select name="medium"><option value="">Não informado</option><option value="pdf">PDF / leitura</option><option value="video">Videoaula</option><option value="tec">TEC / questões</option></select></label><div></div><label>Página / minuto inicial<input type="number" min="0" step="any" name="start"></label><label>Página / minuto final<input type="number" min="0" step="any" name="end"></label><label class="full">Anotações<textarea name="notes" placeholder="O que estudar na próxima sessão? Dúvidas, grifos, questões…"></textarea></label><label class="check full"><input type="checkbox" name="applyCycle" ${checks(!!defaults.activity&&defaults.activity!=='night'&&defaults.activity!=='free'&&sid===currentSubject().id)}> Abater este tempo do bloco atual do ciclo</label><small class="full">Sessões de teoria podem ser registradas no ponto real em que você está. Para marcar uma unidade como concluída, liberar baterias e checkpoints, a validação formal do Método ET continua sendo feita em Disciplinas.</small><button type="submit" class="full">Salvar registro</button></form>`);$('#session-subject').onchange=e=>{$('#session-unit').innerHTML=unitOptions(subject(e.target.value));refreshSessionContent();};$('#session-unit').onchange=refreshSessionContent;$('#session-activity').onchange=e=>{if(e.target.value==='free')$('#session-form').elements.applyCycle.checked=false;if(e.target.value==='night'){$('#session-form').elements.applyCycle.checked=false;$('#session-form').elements.hours.value=0;$('#session-form').elements.durationMinutes.value=5;}};$('#session-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(String(d.customTitle||'').trim())d.title=String(d.customTitle).trim();delete d.customTitle;try{d.minutes=durationMinutes(d.hours,d.durationMinutes);}catch(error){toast(error.message,true);return;}d.applyCycle=e.target.elements.applyCycle.checked;if(change(()=>M.session(state,d))){if(defaults.fromTimer){let remainder=Math.max(0,timer.elapsed-Number(d.minutes)*60000);timer=remainder?{...timer,elapsed:remainder,running:false}:null;saveTimer();}close();render();}};}
function unitOptions(s,id=''){return option('','Selecionar aula / módulo',id)+s.units.map(u=>option(u.id,String(u.order).padStart(2,'0')+' · '+u.title,id)).join('');}
function unitDialog(id){let s=subject(),u=s.units.find(u=>u.id===id);open(`<h2>${esc(u.title)}</h2><p class="muted">${M.unitSituation(u)}</p>${u.legacy.length?`<details><summary>Conferir ${u.legacy.length} evidências do StudyOS</summary><ul class="evidence">${u.legacy.map(e=>`<li>${esc(e.date||'')} ${esc(e.title)} · ${esc(e.status)}${e.notes?' · '+esc(e.notes):''}</li>`).join('')}</ul></details>`:''}<form id="unit-form"><label class="check"><input name="theoryDone" type="checkbox" ${checks(u.theoryDone)}> Teoria concluída para toda esta ${s.id==='afo'?'unidade (módulo completo)':'aula'}</label>${u.legacy.length&&!u.theoryDone?'<small>Histórico StudyOS encontrado: você pode confirmar a teoria na data real sem marcar bateria ou checkpoint.</small>':''}<label>Data real da conclusão da teoria<input name="theoryDate" type="date" max="${M.day()}" value="${u.theoryDate||suggestedTheoryDate(u)}"></label><label class="check"><input name="batteryDone" type="checkbox" ${checks(u.batteryDone)}> Primeira bateria concluída (${u.battery.attempted} questões registradas)</label><small>Resolva de 30 a 50 questões distribuídas por toda a aula. Selecione questões alternadas de 3 em 3 ou 5 em 5, ajustando à cobertura do conteúdo.</small><label class="check"><input name="generalDone" type="checkbox" ${checks(u.generalDone)}> Revisão geral concluída</label><label class="check"><input name="materialReady" type="checkbox" ${checks(u.materialReady)}> Material de revisão pronto / adaptado</label><div class="actions"><button type="submit">Salvar etapa</button><button type="button" class="secondary" id="unit-session">Registrar tempo / questões</button></div></form><p class="muted" style="font-size:13px;margin-top:18px">Marque as questões erradas, difíceis e de síntese no próprio PDF. Na app, registre apenas os totais e acertos da bateria.</p>`);$('#unit-form').onsubmit=e=>{e.preventDefault();let f=e.target.elements;if(change(()=>M.setUnit(state,s.id,u.id,{theoryDone:f.theoryDone.checked,theoryDate:f.theoryDate.value,batteryDone:f.batteryDone.checked,generalDone:f.generalDone.checked,materialReady:f.materialReady.checked})))close();};$('#unit-session').onclick=()=>{close();sessionDialog({subjectId:s.id,unitId:u.id,activity:u.theoryDone&&!u.batteryDone?'battery':'theory'});};}

function checkpointDialog(id){let s=subject(),cp=M.checkpoints(s).find(c=>c.id===id);open(`<h2>Checkpoint ${cp.number} · ${label(s.id)}</h2><p class="muted">${cpLabel[cp.status]}. Retome questões erradas, difíceis e de síntese: até 20 por ${s.id==='afo'?'módulo':'aula'}.</p>${cp.status==='audit'?'<div class="warning">O histórico indica estudo deste bloco. Confira as datas e etapas de cada unidade para validar a pendência.</div>':''}<form id="cp-form">${cp.units.map(u=>`<div class="card" style="margin:12px 0;padding:16px"><h3>${u.order}. ${esc(u.title)}</h3><small>${M.unitSituation(u)}</small><p class="muted" style="font-size:13px">Abra o PDF desta unidade e retome suas marcações. Informe abaixo apenas o resultado total.</p><div class="form-grid"><label>Resolvidas<input name="${u.id}-attempted" type="number" min="1" max="20" value="${cp.record?.perUnit?.[u.id]?.attempted||''}" required ${cp.status==='done'?'disabled':''}></label><label>Acertos<input name="${u.id}-correct" type="number" min="0" max="20" value="${cp.record?.perUnit?.[u.id]?.correct??''}" required ${cp.status==='done'?'disabled':''}></label></div></div>`).join('')}${cp.status==='due'?'<button>Concluir checkpoint</button><p class="muted" style="font-size:12px;margin-top:10px">Registre o tempo gasto separadamente no diário como Checkpoint.</p>':`<small>${cp.status==='done'?'Concluído em '+cp.record.date:'Conclua a teoria e a primeira bateria de todas as unidades para liberar este checkpoint.'}</small>`}</form>`);$('#cp-form').onsubmit=e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target)),r=Object.fromEntries(cp.units.map(u=>[u.id,{attempted:values[u.id+'-attempted'],correct:values[u.id+'-correct']}]));if(change(()=>M.finishCheckpoint(state,s.id,id,r)))close();};}
function importDialog(){open('<h2>Importar backup</h2><p class="muted">Escolha o JSON exportado pelo StudyOS ou pelo Metodo-ET.</p><label>Arquivo JSON<input type="file" id="import-file" accept=".json,application/json"></label><div id="import-preview"></div>');$('#import-file').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024)throw Error('O arquivo ultrapassa 20 MB.');let payload=JSON.parse(await file.text()),isET=payload.version===1&&Array.isArray(payload.subjects),next=isET?normalizeExtras(M.validate(payload)):normalizeExtras(M.migrate(payload,state));pendingImport={next,isET,base:storedRaw};$('#import-preview').innerHTML=`<div class="warning">${isET?'Restaurar Metodo-ET substitui os registros deste navegador. Exporte seu backup atual antes de continuar.':'Mesclar StudyOS preserva os registros locais e evita repetir sessões já importadas.'}</div><p>${next.sessions.length} sessões após importar · ${next.subjects.length} disciplinas ativas · ${next.reminders.length} lembretes.</p><div class="actions"><button data-action="export" class="secondary">Exportar dados atuais</button><button data-action="import-apply">${isET?'Restaurar estes dados':'Mesclar registros'}</button></div>`;}catch(e){pendingImport=null;$('#import-preview').textContent=e.message;}};}
function saveTimer(){try{if(timer)localStorage.setItem(M.KEY+':timer',JSON.stringify(timer));else localStorage.removeItem(M.KEY+':timer');}catch{toast('O cronômetro está apenas em memória. Registre o tempo antes de fechar a página.',true);}}
function elapsed(){return timer?timer.elapsed+(timer.running?Date.now()-timer.started:0):0;}
function updateClock(){let el=$('#clock');if(!el)return;let sec=Math.floor(elapsed()/1000);el.textContent=[Math.floor(sec/3600),Math.floor(sec/60)%60,sec%60].map(n=>String(n).padStart(2,'0')).join(':');}
function startTimer(){let s=currentSubject();open(`<h2>Iniciar foco · ${label(s.id)}</h2><form id="timer-form"><label>Aula ou módulo<select name="unitId">${unitOptions(s,s.units.find(u=>!u.theoryDone||!u.batteryDone)?.id)}</select></label><label style="margin-top:16px">Atividade<select name="activity">${Object.entries(M.ACTIVITIES).filter(([id])=>id!=='night').map(([id,t])=>option(id,t,'theory')).join('')}</select></label><button style="margin-top:20px">Iniciar cronômetro</button></form>`);$('#timer-form').onsubmit=e=>{e.preventDefault();let f=e.target.elements,u=s.units.find(u=>u.id===f.unitId.value);timer={subjectId:s.id,unitId:u?.id||'',title:u?.title||'Estudo livre',activity:f.activity.value,elapsed:0,started:Date.now(),running:true};saveTimer();close();render();};}
document.addEventListener('click',e=>{let b=e.target.closest('[data-select],[data-action]');if(!b)return;if(b.dataset.select){selected=b.dataset.select;render();return;}let a=b.dataset.action,id=b.dataset.id;try{if(a==='reminder-new')reminderDialog();if(a==='motivation-open')motivationDialog();if(a==='session')sessionDialog();if(a==='night')sessionDialog({subjectId:id,activity:'night',minutes:5});if(a==='go-subject'){selected=currentSubject().id;location.hash='subjects';}if(a==='unit')unitDialog(id);if(a==='checkpoint')checkpointDialog(id);if(a==='export')backup();if(a==='import')importDialog();if(a==='import-apply'&&pendingImport){if(pendingImport.base!==storedRaw)throw Error('Os registros mudaram. Selecione o arquivo novamente.');if(change(()=>pendingImport.next,'Importação concluída.')){pendingImport=null;close();}}if(a==='timer-start')startTimer();if(a==='timer-toggle'){timer.elapsed=elapsed();timer.running=!timer.running;timer.started=Date.now();saveTimer();render();}if(a==='timer-save'){if(elapsed()<60000)throw Error('Registre após completar pelo menos um minuto.');timer.elapsed=elapsed();timer.running=false;saveTimer();render();sessionDialog({...timer,minutes:Math.floor(timer.elapsed/60000),fromTimer:true});}if(a==='law-manual')lawManualDialog();if(a==='law-timer-start'){let n=currentLaw();lawTimer={normId:n.id,elapsed:0,started:Date.now(),running:true};saveLawTimer();render();}if(a==='law-timer-toggle'){lawTimer.elapsed=lawElapsed();lawTimer.running=!lawTimer.running;lawTimer.started=Date.now();saveLawTimer();render();}if(a==='law-timer-save'){if(lawElapsed()<60000)throw Error('Registre após completar pelo menos um minuto.');let mins=Math.max(1,Math.floor(lawElapsed()/60000));lawTimer.elapsed=lawElapsed();lawTimer.running=false;saveLawTimer();lawManualDialog(mins,'timer');lawTimer=null;saveLawTimer();}if(a==='law-complete')completeLawDialog();if(a==='to-solid'){open('<h2>Reduzir carga e entrar no Estudo Sólido</h2><form id="solid-form"><label>Minutos por bloco<input name="minutes" type="number" min="30" max="'+(subject().slotMinutes-1)+'" value="60" required></label><button style="margin-top:18px">Confirmar transição</button></form>');$('#solid-form').onsubmit=e=>{e.preventDefault();if(change(()=>M.switchSolid(state,selected,e.target.elements.minutes.value)))close();};}if(a==='notebook-new'){open('<h2>Novo caderno TEC</h2><form id="notebook-form" class="form-grid"><label class="full">Nome<input name="title" required></label><label class="full">Link TEC<input name="url" type="url" placeholder="https://..."></label><label>Total de questões<input type="number" name="target" min="1" required></label><button class="full">Criar caderno</button></form>');$('#notebook-form').onsubmit=e=>{e.preventDefault();let f=e.target.elements;if(change(()=>M.addNotebook(state,selected,f.title.value,f.url.value,f.target.value)))close();};}if(a==='notebook-round'){let n=subject().notebooks.find(n=>n.id===id);open(`<h2>Concluir rodada</h2><p>${esc(n.title)}</p><form id="round-form" class="form-grid"><label>Questões resolvidas<input type="number" name="attempted" min="0" required value="${n.stage==='main'?n.target:n.stage==='errors'?n.errors:''}"></label><label>Acertos<input type="number" name="correct" min="0" required></label><small class="full">Informe a rodada completa. Nas favoritas, zero é permitido se nenhuma foi marcada.</small><button class="full">Salvar resultados</button></form>`);$('#round-form').onsubmit=e=>{e.preventDefault();if(change(()=>M.notebookRound(state,selected,id,e.target.elements.attempted.value,e.target.elements.correct.value)))close();};}if(a==='csv'){let cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"',rows=[['Data','Disciplina','Aula','Forma','Formato','Início','Fim','Minutos','Questões','Acertos','Notas'],...filteredHistory().map(s=>[s.date,label(s.subjectId),s.title,M.ACTIVITIES[s.activity],s.medium,s.start,s.end,s.minutes,s.questions,s.correct,s.notes])];download('Metodo-ET-diario.csv','\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}}catch(e){toast(e.message,true);}});
document.addEventListener('change',e=>{if(e.target.matches?.('[data-reminder-status]')){let f=e.target.closest('form');change(()=>saveReminder(state,{id:f.dataset.reminderForm,text:f.elements.text.value,status:f.elements.status.value}),'Lembrete salvo.');}if(e.target.id==='andresan')change(()=>{let next=M.copy(state),s=next.subjects.find(s=>s.id==='port');s.andresanComplete=e.target.checked;if(!s.andresanComplete)s.phase='new';return next;});if(e.target.id.startsWith('history-'))$('#history-results').innerHTML=historyRows();});
window.addEventListener('hashchange',()=>{render();});
window.addEventListener('storage',e=>{if(e.key===M.KEY){toast('Os dados foram alterados em outra aba. Recarregue para continuar.',true);}});
setInterval(()=>{updateClock();updateLawClock();const d=M.day();if(lastMotivationDay!==d){lastMotivationDay=d;if(page==='motivation')render();else if(page==='reminders'){let panel=$('#daily-motivation');if(panel)panel.innerHTML=motivationCard();}}},1000);
let lastMotivationDay=M.day();
async function init(){try{storedRaw=localStorage.getItem(M.KEY);state=storedRaw?M.validate(JSON.parse(storedRaw)):M.validate(await fetch('./data/initial-state.json').then(r=>{if(!r.ok)throw Error('Base inicial indisponível.');return r.json();}));state=normalizeExtras(state);if(!storedRaw||!JSON.parse(storedRaw).motivationStartDay||!Array.isArray(JSON.parse(storedRaw).reminders)||!JSON.parse(storedRaw).legislation)persist(state);let t=localStorage.getItem(M.KEY+':timer');if(t){let saved=JSON.parse(t);if(state.subjects.some(s=>s.id===saved.subjectId)&&Number.isFinite(saved.elapsed)&&Number.isFinite(saved.started))timer=saved;}let lt=localStorage.getItem(M.KEY+':law-timer');if(lt){let saved=JSON.parse(lt);if(state.legislation.queue.some(n=>n.id===saved.normId)&&Number.isFinite(saved.elapsed)&&Number.isFinite(saved.started))lawTimer=saved;}$('#date-label').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});render();}catch(e){main.innerHTML='<h1>Não foi possível abrir seus dados.</h1><p id="load-error"></p><p>Os registros locais não foram substituídos. Exporte-os para conferir o arquivo antes de restaurar.</p><button id="recover">Baixar dados locais</button>';$('#load-error').textContent=e.message;$('#recover').onclick=()=>download('Metodo-ET-recuperacao.json',storedRaw||'{}');}}
init();

function remindersPage(){let notes=state.reminders||[],statuses={todo:'A fazer',done:'Feito',future:'Futuramente'};return heading('SEU MURAL','Lembretes','Anote, organize e volte quando precisar.',actionsButton('+ Novo lembrete','reminder-new'))+`<div class="notes-grid">${Object.entries(statuses).map(([status,title])=>`<section class="notes-column"><h2>${title} <span class="note-count">${notes.filter(n=>n.status===status).length}</span></h2>${notes.filter(n=>n.status===status).map(n=>`<form class="sticky sticky-${n.status}" data-reminder-form="${esc(n.id)}"><label class="sr-only" for="note-${esc(n.id)}">Texto do lembrete</label><textarea id="note-${esc(n.id)}" name="text" maxlength="5000" required>${esc(n.text)}</textarea><label>Situação<select name="status" data-reminder-status>${Object.entries(statuses).map(([v,t])=>option(v,t,n.status)).join('')}</select></label><button class="small" type="submit">Salvar texto</button></form>`).join('')||'<p class="empty note-empty">Nenhum lembrete aqui.</p>'}</section>`).join('')}</div><section class="section-title"><h2>Lembre-se sempre!</h2><div id="daily-motivation">${motivationCard()}</div></section>`;}
function reminderDialog(){open('<h2>Novo lembrete</h2><form id="reminder-form" class="form-grid"><label class="full">O que você quer lembrar?<textarea name="text" maxlength="5000" rows="6" placeholder="Escreva aqui…" required></textarea></label><label class="full">Situação<select name="status"><option value="todo">A fazer</option><option value="done">Feito</option><option value="future">Futuramente</option></select></label><button class="full">Adicionar ao mural</button></form>');$('#reminder-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements;if(change(()=>saveReminder(state,{text:f.text.value,status:f.status.value}),'Lembrete adicionado.'))close();};}
function motivationCard(){const item=motivationForDay(state.motivationStartDay);return `<article class="motivation-card"><div class="motivation-top"><div><span class="eyebrow">MENSAGEM DO DIA</span><h3>${esc(item.title)}</h3></div><button class="secondary small" data-action="motivation-open">Ampliar imagem</button></div><button class="motivation-image" data-action="motivation-open" aria-label="Ampliar: ${esc(item.title)}"><img src="./assets/motivation/${item.file}" alt="${esc(item.alt)}" loading="lazy"></button><p class="muted motivation-caption">${item.source} · uma nova mensagem a cada dia</p></article>`;}
function motivationPage(){return heading('FOCO NO QUE VOCÊ CONSTRÓI','Lembre-se sempre!','Uma pausa para lembrar por que você começou.')+motivationCard();}
function motivationDialog(){const item=motivationForDay(state.motivationStartDay);modal.classList.add('image-modal');open(`<h2>${esc(item.title)}</h2><img class="expanded-motivation" src="./assets/motivation/${item.file}" alt="${esc(item.alt)}"><p class="muted">${item.source}</p>`);}
modal.addEventListener?.('close',()=>modal.classList.remove('image-modal'));
document.addEventListener('submit',e=>{const f=e.target.closest?.('[data-reminder-form]');if(!f)return;e.preventDefault();change(()=>saveReminder(state,{id:f.dataset.reminderForm,text:f.elements.text.value,status:f.elements.status.value}),'Texto do lembrete salvo.');});

function progressPage(){
 const p=progressMetrics(state),number=n=>Number(n).toLocaleString('pt-BR'),percent=n=>n===null?'—':n.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%',resultDetail=r=>r?`${esc(label(r.subjectId))} · ${r.correct}/${r.questions} questões · ${r.date.split('-').reverse().join('/')}`:'Nenhuma sessão com questões registradas';
 return heading('CADA SESSÃO CONTA','Progresso','Veja o que você já construiu, incluindo seu histórico do StudyOS.',actionsButton('+ Registrar estudo','session'))+`<p class="muted progress-explanation">StudyOS importado: ${esc((state.imports.map(i=>i.sourceUpdatedAt).filter(Boolean).sort().at(-1)||'').slice(0,10).split('-').reverse().join('/')||'data não informada')}. Novos registros desta app são somados automaticamente.</p><div class="grid metrics progress-metrics"><section class="card metric"><small>CARGA HORÁRIA ESTUDADA</small><strong>${M.hm(p.minutes)}</strong><span class="sub">${number(p.sessions)} sessões · sem revisão noturna</span></section><section class="card metric"><small>QUESTÕES FEITAS</small><strong>${number(p.questions)}</strong><span class="sub">${number(p.correct)} acertos registrados no diário</span></section><section class="card metric"><small>APROVEITAMENTO GERAL</small><strong>${percent(p.accuracy)}</strong><span class="sub">Acertos ÷ questões · média ponderada</span></section></div><div class="grid progress-highlights"><section class="card metric"><small>MELHOR PERCENTUAL · SESSÃO</small><strong>${percent(p.best?p.best.correct/p.best.questions*100:null)}</strong><span class="sub">${resultDetail(p.best)}</span></section><section class="card metric"><small>MENOR PERCENTUAL · SESSÃO</small><strong>${percent(p.worst?p.worst.correct/p.worst.questions*100:null)}</strong><span class="sub">${resultDetail(p.worst)}</span></section><section class="card metric"><small>SEQUÊNCIA ATUAL</small><strong>${p.streak.current} <span class="metric-unit">dias</span></strong><span class="sub">${p.streak.current?'Continue construindo sua constância.':'Sua próxima sessão pode iniciar uma nova sequência.'}</span></section><section class="card metric"><small>SEU RECORDE</small><strong>${p.streak.best} <span class="metric-unit">dias</span></strong><span class="sub">Maior sequência de dias com estudo</span></section></div><section class="card section-title"><div class="page-head"><div><h2>Progresso por disciplina</h2><p>Seu histórico e seus novos estudos, por módulo ou aula do curso atual.</p></div><a href="#subjects">Conferir etapas →</a></div><div class="table-wrap"><table class="progress-table"><thead><tr><th>DISCIPLINA</th><th>AVANÇO NO CONTEÚDO</th><th>UNIDADES</th><th>HORAS</th><th>QUESTÕES / ACERTOS</th></tr></thead><tbody>${['afo','dad','ti','port','dcon'].map(id=>p.disciplines.find(d=>d.id===id)).filter(Boolean).map(d=>`<tr><td><b>${label(d.id)}</b></td><td class="discipline-bar"><div class="bar-line"><progress value="${d.started}" max="${d.total||1}" aria-label="Unidades iniciadas ou concluídas em ${label(d.id)}"></progress><b>${percent(d.startedPercent)}</b></div><small class="progress-detail">${percent(d.percent)} com teoria concluída</small></td><td>${d.started}/${d.total} ${d.unit==='módulo'?'módulos':'aulas'}<small class="progress-detail">${d.completed} concluídos · ${d.started-d.completed} em andamento</small></td><td>${M.hm(d.minutes)}</td><td>${number(d.questions)} · ${percent(d.questions?d.correct/d.questions*100:null)}</td></tr>`).join('')}</tbody></table></div><p class="muted progress-explanation">A barra mostra unidades iniciadas ou concluídas, incluindo o StudyOS, sem precisar recadastrar os estudos. O percentual de teoria concluída aparece abaixo: “Estudando” indica andamento; “Revisado” na aula inteira indica conclusão. Em AFO, cada módulo conta uma única vez; revisar um vídeo isolado não conclui o módulo. Baterias, checkpoints e revisão geral ET mantêm seus próprios controles. O histórico de cursos anteriores de Português soma horas e questões, mas não conclui aulas do curso atual nem do Andresan.</p></section><div class="grid two section-title"><section class="card"><h2>Sua constância</h2><div class="statline"><span><b>${p.streak.days}</b> dias de estudo no histórico</span><span><b>${M.hm(p.nightMinutes)}</b> de revisão noturna à parte</span></div><p class="muted progress-explanation">Conta um dia com qualquer registro de estudo, inclusive livre. Revisão noturna sozinha não conta. Domingo de descanso não interrompe a sequência nem acrescenta um dia; domingo estudado conta. O dia de hoje permanece aberto até terminar. Esta sequência mede presença, não cumprimento da carga diária.</p></section><section class="card"><h2>Como ler seus resultados</h2><p class="muted progress-explanation">Horas e questões vêm do diário, incluindo registros importados. Questões refeitas contam como novas tentativas. O melhor e o menor percentual comparam sessões com ao menos uma questão; observe também o tamanho de cada bateria.</p><p class="muted progress-explanation">Os percentuais de checkpoints e cadernos controlam suas etapas. Eles não são somados novamente ao total do diário, para evitar duplicidade. Registre no diário o total de questões efetivamente resolvidas em cada sessão.</p></section></div>`;
}
